<form method="get" class="filter-row"><input class="form-control" type="date" name="start" value="<?= e($start) ?>" aria-label="Từ ngày"><input class="form-control" type="date" name="end" value="<?= e($end) ?>" aria-label="Đến ngày"><select class="form-select" name="group" aria-label="Nhóm thời gian"><option value="day">Theo ngày</option><option value="month" <?= $group==='month'?'selected':'' ?>>Theo tháng</option></select><select class="form-select" name="payment_status" aria-label="Trạng thái thanh toán"><option value="">Mọi trạng thái tiền</option><?php foreach(['unpaid','paid','refunded'] as $s):?><option value="<?= $s ?>" <?= $payment_status===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach?></select><button class="btn btn-primary" type="submit">Đối chiếu</button></form><div class="metrics"><?php foreach(['revenue'=>'Doanh thu đơn hoàn thành','received'=>'Tiền đã thu','refunded'=>'Tiền đã hoàn','unpaid'=>'Ghi nhận chưa thu'] as $key=>$label):?><div class="metric"><small><?= $label ?></small><strong style="font-size:22px"><?= money(array_sum(array_column($rows,$key))) ?></strong><span>Trong khoảng thời gian đã chọn</span></div><?php endforeach?></div><section class="panel"><h2>Thu tiền & hoàn tiền</h2><div style="height:300px"><canvas id="revenue-chart" data-rows="<?= e(json_encode($rows,JSON_THROW_ON_ERROR)) ?>" aria-label="Biểu đồ thu hoàn tiền"></canvas></div></section><section class="panel table-wrap"><h2>Bảng đối chiếu</h2><p class="muted small">Doanh thu theo ngày hoàn thành đơn; tiền theo ngày thanh toán. Lọc trạng thái chỉ áp dụng sổ thanh toán. Dòng chưa thu là ghi chú, không cộng vào tiền thực thu.</p><table class="table"><thead><tr><th>Kỳ</th><th>Đơn hoàn thành</th><th>Doanh thu</th><th>Đã thu</th><th>Hoàn tiền</th><th>Thu ròng</th><th>Chưa thu (ghi chú)</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e($r['period']) ?></td><td><?= $r['completed'] ?></td><td><?= money($r['revenue']) ?></td><td><?= money($r['received']) ?></td><td><?= money($r['refunded']) ?></td><td><?= money((int)$r['received']-(int)$r['refunded']) ?></td><td><?= money($r['unpaid']) ?></td></tr><?php endforeach?></tbody></table></section>
